pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(value) = bytes.strip_prefix("v:2:hello:") {
        return Ok(Msg::Hello(value.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2:heartbeat:") {
        return sequence
            .parse::<u32>()
            .map(Msg::Heartbeat)
            .map_err(|_| "unknown".into());
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2:hello:{value}"),
        Msg::Heartbeat(sequence) => format!("v:2:heartbeat:{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_roundtrips_with_v2_envelope() {
        let message = Msg::Hello("world".into());
        assert_eq!(encode(&message), "v:2:hello:world");
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Hello(value)) if value == "world"));
    }

    #[test]
    fn heartbeat_roundtrips_with_v2_envelope() {
        let message = Msg::Heartbeat(42);
        assert_eq!(encode(&message), "v:2:heartbeat:42");
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
